# ----------------------------------------------------------------------------------------------------------------------------------
# Narration / kinetic type.  kind: title | label | note | fine.   pos: where in the frame (see layout templates).
# fx: SLAM POP TYPE STAMP SWIPE DRAW DROP SLIDE (entrances; exits happen on the cut or with a 4-frame pop-out)
# ----------------------------------------------------------------------------------------------------------------------------------
def T(id, start, end, text, font, size, style, pos, fx, kind='title', src=''):
    return dict(id=id, start=start, end=end, text=text, font=font, size=size, style=style, pos=pos, fx=fx, kind=kind, src=src)

